WITH датчик AS (INSERT INTO project_sensor_spec (project_id, fact, reads, extract_re, how) VALUES ($1::text, 'design-ad-hoc-date', 'probe-selftest/**/*.tsx', '\.toLocale(Date|Time)?String\(', 'lines') ON CONFLICT (project_id, fact) DO NOTHING RETURNING 1) INSERT INTO code_fact (project_id, kind, name, detail) VALUES ($1::text, 'design-ad-hoc-date', 'probe-selftest/ui/App.tsx:1', 'new Date(at).toLocaleDateString()')
